                            "properties": {
                                "arguments": {
                                    "description": "Specify any additional parameters that should be added to the pull command when pulling an execution environment from a container registry. e.g. --pa='--tls-verify=false'",
                                    "items": {
                                        "type": "string"
                                    },
                                    "type": "array"
                                },
                                "policy": {
                                    "default": "tag",
                                    "description": "Specify the image pull policy always:Always pull the image, missing:Pull if not locally available, never:Never pull the image, tag:if the image tag is 'latest', always pull the image, otherwise pull if not locally available",
                                    "enum": [
                                        "always",
                                        "missing",
                                        "never",
                                        "tag"
                                    ],
                                    "type": "string"
                                }
                            }
                        },
                        "volume-mounts": {
                            "additionalProperties": false,
                            "description": "Specify volume to be bind mounted within an execution environment (--eev /home/user/test:/home/user/test:Z)",
                            "items": {
                                "additionalProperties": false,
                                "properties": {
                                    "dest": {
                                        "type": "string"
                                    },
                                    "options": {
                                        "type": "string"
                                    },
                                    "src": {
                                        "type": "string"
                                    }
                                },
                                "required": [
                                    "src",
                                    "dest"
                                ],
                                "type": "object"
                            },
                            "type": "array"
                        }
                    },
                    "type": "object"
                },
                "format": {
                    "default": "yaml",
                    "description": "Specify the format for stdout output.",
                    "enum": [
                        "json",
                        "yaml"
                    ],
                    "type": "string"
                },
                "images": {
                    "additionalProperties": false,
                    "properties": {
                        "details": {
                            "default": [
                                "everything"
                            ],
                            "description": "Provide detailed information about the selected execution environment image",
                            "items": {
                                "enum": [
                                    "ansible_collections",
                                    "ansible_version",
                                    "everything",
                                    "os_release",
                                    "python_packages",
                                    "python_version",
                                    "redhat_release",
                                    "system_packages"
                                ],
                                "type": "string"
                            },
                            "type": "array"
                        }
                    }
                },
                "inventory-columns": {
                    "description": "Specify a host attribute to show in the inventory view",
                    "items": {
                        "type": "string"
                    },
                    "type": "array"
                },
                "logging": {
                    "additionalProperties": false,
                    "properties": {
                        "append": {
                            "default": true,
                            "description": "Specify if log messages should be appended to an existing log file, otherwise a new log file will be created per session",
                            "enum": [
                                true,
                                false
                            ],
                            "type": "boolean"
                        },
                        "file": {
                            "default": "./ansible-navigator.log",
                            "description": "Specify the full path for the ansible-navigator log file",
                            "type": "string"
                        },
                        "level": {
                            "default": "warning",
                            "description": "Specify the ansible-navigator log level",
                            "enum": [
                                "debug",
                                "info",
                                "warning",
                                "error",
                                "critical"
                            ],
                            "type": "string"
                        }
                    },
                    "type": "object"
                },
                "mode": {
                    "default": "interactive",
                    "description": "Specify the user-interface mode",
                    "enum": [
                        "stdout",
                        "interactive"
                    ],
                    "type": "string"
                },
                "playbook-artifact": {
                    "additionalProperties": false,
                    "properties": {
                        "enable": {
                            "default": true,
                            "description": "Enable or disable the creation of artifacts for completed playbooks. Note: not compatible with '--mode stdout' when playbooks require user input",
                            "enum": [
                                true,
                                false
                            ],
                            "type": "boolean"
                        },
                        "replay": {
                            "description": "Specify the path for the playbook artifact to replay",
                            "type": "string"
                        },
                        "save-as": {
                            "default": "{playbook_dir}/{playbook_name}-artifact-{time_stamp}.json",
                            "description": "Specify the name for artifacts created from completed playbooks. The following placeholders are available: {playbook_dir}, {playbook_name}, {playbook_status}, and {time_stamp}",
                            "type": "string"
                        }
                    },
                    "type": "object"
                },
                "settings": {
                    "additionalProperties": false,
                    "properties": {
                        "effective": {
                            "default": false,
                            "description": "Show the effective settings. Defaults, CLI parameters, environment variables, and the settings file will be combined",
                            "type": "boolean"
                        },
                        "sample": {
                            "default": false,
                            "description": "Generate a sample settings file",
                            "type": "boolean"
                        },
                        "schema": {
                            "default": "json",
                            "description": "Generate a schema for the settings file ('json'= draft-07 JSON Schema)",
                            "enum": [
                                "json"
                            ],
                            "type": "string"
                        },
                        "sources": {
                            "default": false,
                            "description": "Show the source of each current settings entry",
                            "type": "boolean"
                        }
                    }
                },
                "time-zone": {
                    "default": "UTC",
                    "description": "Specify the IANA time zone to use or 'local' to use the system time zone",
                    "type": "string"
                }
            }
        }
    },
    "required": [
        "ansible-navigator"
    ],
    "title": "ansible-navigator settings v3",
    "type": "object",
    "version": "3"
}

{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "definitions": {
    "jsBundle": {
      "properties": {
        "outputFileName": {
          "pattern": "\\.js$"
        },
        "sourceMap": {
          "description": "JavaScript only. Set to true to produce a source map.",
          "type": "boolean"
        },
        "sourceMapRootPath": {
          "description": "JavaScript only. Sets a root path for source maps.",
          "type": "string",
          "default": ""
        },
        "minify": {
          "type": "object",
          "properties": {
            "alwaysEscapeNonAscii": {
              "description": "JavaScript only. Gets or sets a flag indicating whether to always escape non-ASCII characters as \\uXXXX or to let the output encoding object handle that via the JsEncoderFallback object for the specified output encoding format.",
              "type": "boolean",
              "default": false
            },
            "evalTreatment": {
              "description": "JavaScript only.",
              "enum": ["ignore", "makeAllSafe", "makeImmediateSafe"],
              "default": "ignore"
            },
            "preserveImportantComments": {
              "description": "JavaScript only.",
              "type": "boolean",
              "default": true
            },
            "renameLocals": {
              "description": "JavaScript only. Controls if local variables should be shortened.",
              "type": "boolean",
              "default": true
            },
            "termSemicolons": {
              "description": "Forces all rules to be terminated with semicolons if set to true.",
              "type": "boolean",
              "default": true
            }
          },
          "allOf": [
            {
              "$ref": "#/definitions/ajaxminBaseSettings"
            }
          ]
        }
      }
    },
    "cssBundle": {
      "properties": {
        "outputFileName": {
          "pattern": "\\.css$"
        },
        "minify": {
          "type": "object",
          "properties": {
            "colorNames": {
              "description": "CSS only. If no color names are to be used, set this value to 'hex'. If a set of colors recognized by all major browser is okay to use (W3C-strict validation is not required), set this value to 'major'.",
              "enum": ["hex", "major", "noSwap", "strict"],
              "default": "strict"
            },
            "commentMode": {
              "description": "CSS only. How to treat comments in the code. The default is 'none', which will strip all comments except 'important' comments. 'all' will leave all comments, and 'hacks' will only leave certain known comment-based hacks.",
              "enum": ["none", "all", "hacks", "important"],
              "default": "important"
            },
            "adjustRelativePaths": {
              "description": "CSS only. Adjust relative paths inside the url() function.",
              "type": "boolean",
              "default": true
            },
            "termSemicolons": {
              "description": "Forces all rules to be terminated with semicolons if set to true.",
              "type": "boolean",
              "default": false
            }
          },
          "allOf": [
            {
              "$ref": "#/definitions/ajaxminBaseSettings"
            }
          ]
        }
      }
    },
    "htmlBundle": {
      "properties": {
        "outputFileName": {
          "pattern": "\\.(html|htm)$"
        },
        "minify": {
          "type": "object",
          "properties": {
            "collapseBooleanAttributes": {
              "description": "HTML only. Remove values from boolean attributes.",
              "type": "boolean",
              "default": true
            },
            "collapseWhitespace": {
              "description": "HTML only. Indicating whether to collapse whitespaces.",
              "type": "boolean",
              "default": true
            },
            "isFragmentOnly": {
              "description": "HTML only. Indicating whether the parsing is occurring on an HTML fragment, to avoid creating missing tags (like html, body, head).",
              "type": "boolean",
              "default": true
            },
            "keepOneSpaceWhenCollapsing": {
              "description": "HTML only. Indicating whether to keep one space when collapsing.",
              "type": "boolean",
              "default": false
            },
            "minifyEmbeddedCssCode": {
              "description": "HTML only. Minify CSS code in style tags.",
              "type": "boolean",
              "default": true
            },
            "minifyEmbeddedJsCode": {
              "description": "HTML only. Minify JS code in script tags.",
              "type": "boolean",
              "default": true
            },
            "minifyInlineCssCode": {
              "description": "HTML only. Minify CSS code in style attributes.",
              "type": "boolean",
              "default": true
            },
            "preserveCase": {
              "description": "HTML only. Preserve case of tag and attribute names.",
              "type": "boolean",
              "default": false
            },
            "removeHtmlComments": {
              "description": "HTML only. Remove all HTML comments except conditional, noindex, Knockout.js containerless comments and Angular.js comment directives.",
              "type": "boolean",
              "default": true
            },
            "removeOptionalEndTags": {
              "description": "HTML only. Remove optional end tags.",
              "type": "boolean",
              "default": false
            },
            "removeQuotedAttributes": {
              "description": "HTML only. Indicating whether to remove quoted attributes when possible.",
              "type": "boolean",
              "default": true
            }
          }
        }
      }
    },
    "ajaxminBaseSettings": {
      "properties": {
        "indentSize": {
          "description": "For the multi-line output feature, how many spaces to use when indenting a block (see outputMode).",
          "type": "integer",
          "default": 2
        },
        "outputMode": {
          "description": "SingleLine minifies everything to a single line. MultipleLines breaks the minified code into multiple lines for easier reading.",
          "enum": ["multipleLines", "singleLine", "none"],
          "default": "singleLine"
        }
      }
    },
    "bundle": {
      "required": ["outputFileName", "inputFiles"],
      "properties": {
        "includeInProject": {
          "description": "Set to true to include the output file in the project. Doesn't work in some Visual Studio project types like ASP.NET Core applications.",
          "type": "boolean",
          "default": true
        },
        "inputFiles": {
          "description": "One or more relative file names or globbing patterns to bundle. Example: \"scripts/**/*.js\"",
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "minify": {
          "description": "Specify options for minification of the output file.",
          "type": "object",
          "required": ["enabled"],
          "properties": {
            "enabled": {
              "type": "boolean"
            },
            "gzip": {
              "description": "Produce a .gz file after minification.",
              "type": "boolean",
              "default": false
            }
          }
        },
        "outputFileName": {
          "description": "The relative path to the desired output file name.",
          "type": "string",
          "minLength": 1
        }
      },
      "oneOf": [
        {
          "$ref": "#/definitions/jsBundle"
        },
        {
          "$ref": "#/definitions/cssBundle"
        },
        {
          "$ref": "#/definitions/htmlBundle"
        }
      ]
    }
  },
  "description": "Schema for bundleconfig.json files",
  "id": "https://json.schemastore.org/bundleconfig.json",
  "items": {
    "$ref": "#/definitions/bundle"
  },
  "type": "array"
}

{
  "$id": "https://json.schemastore.org/tmlanguage.json",
  "$ref": "#/definitions/root",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "definitions": {
    "root": {
      "allOf": [
        {
          "$ref": "#/definitions/grammar"
        },
        {
          "type": "object",
          "properties": {
            "name": {
              "type": "string"
            },
            "scopeName": {
              "description": "this should be a unique name for the grammar, following the convention of being a dot-separated name where each new (left-most) part specializes the name. Normally it would be a two-part name where the first is either text or source and the second is the name of the language or document type. But if you are specializing an existing type, you probably want to derive the name from the type you are specializing. For example Markdown is text.html.markdown and Ruby on Rails (rhtml files) is text.html.rails. The advantage of deriving it from (in this case) text.html is that everything which works in the text.html scope will also work in the text.html.«something» scope (but with a lower precedence than something specifically targeting text.html.«something»).",
              "type": "string",
              "pattern": "^(text|source)(\\.[\\w0-9-]+)+$"
            },
            "foldingStartMarker": {
              "description": "regular expressions that lines (in the document) are matched against. If a line matches one of the patterns (but not both), it becomes a folding marker (see the foldings section for more info).",
              "type": "string"
            },
            "foldingStopMarker": {
              "description": "regular expressions that lines (in the document) are matched against. If a line matches one of the patterns (but not both), it becomes a folding marker (see the foldings section for more info).",
              "type": "string"
            },
            "fileTypes": {
              "description": "this is an array of file type extensions that the grammar should (by default) be used with. This is referenced when TextMate does not know what grammar to use for a file the user opens. If however the user selects a grammar from the language pop-up in the status bar, TextMate will remember that choice.",
              "type": "array",
              "items": {
                "type": "string"
              }
            },
            "uuid": {
              "type": "string"
            },
            "firstLineMatch": {
              "type": "string"
            }
          },
          "required": ["scopeName"]
        }
      ]
    },
    "grammar": {
      "type": "object",
      "properties": {
        "patterns": {
          "type": "array",
          "items": {
            "$ref": "#/definitions/pattern"
          },
          "default": []
        },
        "repository": {
          "description": "a dictionary (i.e. key/value pairs) of rules which can be included from other places in the grammar. The key is the name of the rule and the value is the actual rule. Further explanation (and example) follow with the description of the include rule key.",
          "type": "object",
          "additionalProperties": {
            "$ref": "#/definitions/pattern"
          }
        }
      },
      "required": ["patterns"]
    },
    "captures": {
      "type": "object",
      "patternProperties": {
        "^[0-9]+$": {
          "type": "object",
          "properties": {
            "name": {
              "$ref": "#/definitions/name"
            },
            "patterns": {
              "type": "array",
              "items": {
                "$ref": "#/definitions/pattern"
              },
              "default": []
            }
          },
          "additionalProperties": false
        }
      },
      "additionalProperties": false
    },
    "pattern": {
      "type": "object",
      "properties": {
        "comment": {
          "type": "string"
        },
        "disabled": {
          "type": "integer",
          "minimum": 0,
          "maximum": 1,
          "description": "set this property to 1 to disable the current pattern"
        },
        "include": {
          "description": "this allows you to reference a different language, recursively reference the grammar itself or a rule declared in this file's repository.",
          "type": "string"
        },
        "match": {
          "description": "a regular expression which is used to identify the portion of text to which the name should be assigned. Example: '\\b(true|false)\\b'.",
          "type": "string"
        },
        "name": {
          "description": "the name which gets assigned to the portion matched. This is used for styling and scope-specific settings and actions, which means it should generally be derived from one of the standard names.",
          "$ref": "#/definitions/name"
        },
        "contentName": {
          "description": "this key is similar to the name key but only assigns the name to the text between what is matched by the begin/end patterns.",
          "$ref": "#/definitions/name"
        },
        "begin": {
          "description": "these keys allow matches which span several lines and must both be mutually exclusive with the match key. Each is a regular expression pattern. begin is the pattern that starts the block and end is the pattern which ends the block. Captures from the begin pattern can be referenced in the end pattern by using normal regular expression back-references. This is often used with here-docs. A begin/end rule can have nested patterns using the patterns key.",
          "type": "string"
        },
        "end": {
          "description": "these keys allow matches which span several lines and must both be mutually exclusive with the match key. Each is a regular expression pattern. begin is the pattern that starts the block and end is the pattern which ends the block. Captures from the begin pattern can be referenced in the end pattern by using normal regular expression back-references. This is often used with here-docs. A begin/end rule can have nested patterns using the patterns key.",
          "type": "string"
        },
        "while": {
          "description": "these keys allow matches which span several lines and must both be mutually exclusive with the match key. Each is a regular expression pattern. begin is the pattern that starts the block and while continues it.",
          "type": "string"
        },
        "captures": {
          "description": "allows you to assign attributes to the captures of the match pattern. Using the captures key for a begin/end rule is short-hand for giving both beginCaptures and endCaptures with same values.",
          "$ref": "#/definitions/captures"
        },
        "beginCaptures": {
          "description": "allows you to assign attributes to the captures of the begin pattern. Using the captures key for a begin/end rule is short-hand for giving both beginCaptures and endCaptures with same values.",
          "$ref": "#/definitions/captures"
        },
        "endCaptures": {
          "description": "allows you to assign attributes to the captures of the end pattern. Using the captures key for a begin/end rule is short-hand for giving both beginCaptures and endCaptures with same values.",
          "$ref": "#/definitions/captures"
        },
        "whileCaptures": {
          "description": "allows you to assign attributes to the captures of the while pattern. Using the captures key for a begin/while rule is short-hand for giving both beginCaptures and whileCaptures with same values.",
          "$ref": "#/definitions/captures"
        },
        "patterns": {
          "description": "applies to the region between the begin and end matches",
          "type": "array",
          "items": {
            "$ref": "#/definitions/pattern"
          },
          "default": []
        },
        "applyEndPatternLast": {
          "type": "integer",
          "minimum": 0,
          "maximum": 1
        }
      },
      "dependencies": {
        "begin": {
          "anyOf": [
            {
              "required": ["end"]
            },
            {
              "required": ["while"]
            }
          ]
        },
        "end": ["begin"],
        "while": ["begin"],
        "contentName": {
          "anyOf": [
            {
              "required": ["begin", "end"]
            },
            {
              "required": ["begin", "while"]
            }
          ]
        },
        "beginCaptures": {
          "anyOf": [
            {
              "required": ["begin", "end"]
            },
            {
              "required": ["begin", "while"]
            }
          ]
        },
        "whileCaptures": ["begin", "while"],
        "endCaptures": ["begin", "end"],
        "applyEndPatternLast": ["end"]
      }
    },
    "name": {
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "string",
          "enum": [
            "comment",
            "comment.block",
            "comment.block.documentation",
            "comment.line",
            "comment.line.double-dash",
            "comment.line.double-slash",
            "comment.line.number-sign",
            "comment.line.percentage",
            "constant",
            "constant.character",
            "constant.character.escape",
            "constant.language",
            "constant.numeric",
            "constant.other",
            "constant.regexp",
            "constant.rgb-value",
            "constant.sha.git-rebase",
            "emphasis",
            "entity",
            "entity.name",
            "entity.name.class",
            "entity.name.function",
            "entity.name.method",
            "entity.name.section",
            "entity.name.selector",
            "entity.name.tag",
            "entity.name.type",
            "entity.other",
            "entity.other.attribute-name",
            "entity.other.inherited-class",
            "header",
            "invalid",
            "invalid.deprecated",
            "invalid.illegal",
            "keyword",
            "keyword.control",
            "keyword.control.less",
            "keyword.operator",
            "keyword.operator.new",
            "keyword.other",
            "keyword.other.unit",
            "markup",
            "markup.bold",
            "markup.changed",
            "markup.deleted",
            "markup.heading",
            "markup.inline.raw",
            "markup.inserted",
            "markup.italic",
            "markup.list",
            "markup.list.numbered",
            "markup.list.unnumbered",
            "markup.other",
            "markup.punctuation.list.beginning",
            "markup.punctuation.quote.beginning",
            "markup.quote",
            "markup.raw",
            "markup.underline",
            "markup.underline.link",
            "meta",
            "meta.cast",
            "meta.parameter.type.variable",
            "meta.preprocessor",
            "meta.preprocessor.numeric",
            "meta.preprocessor.string",
            "meta.return-type",
            "meta.selector",
            "meta.structure.dictionary.key.python",
            "meta.tag",
            "meta.type.annotation",
            "meta.type.name",
            "metatag.php",
            "storage",
            "storage.modifier",
            "storage.modifier.import.java",
            "storage.modifier.package.java",
            "storage.type",
            "storage.type.cs",
            "storage.type.java",
            "string",
            "string.html",
            "string.interpolated",
            "string.jade",
            "string.other",
            "string.quoted",
            "string.quoted.double",
            "string.quoted.other",
            "string.quoted.single",
            "string.quoted.triple",
            "string.regexp",
            "string.unquoted",
            "string.xml",
            "string.yaml",
            "strong",
            "support",
            "support.class",
            "support.constant",
            "support.function",
            "support.function.git-rebase",
            "support.other",
            "support.property-value",
            "support.type",
            "support.type.property-name",
            "support.type.property-name.css",
            "support.type.property-name.less",
            "support.type.property-name.scss",
            "support.variable",
