          "pattern-propagators": {
            "$ref": "#/$defs/taint-content"
          },
          "pattern-sanitizers": {
            "$ref": "#/$defs/taint-content"
          },
          "join": {
            "$ref": "#/$defs/join-content"
          },
          "fix": {
            "title": "Replacement text to fix matched code. Can use matched metavariables.",
            "type": "string"
          },
          "fix-regex": {
            "type": "object",
            "title": "Replacement regex to fix matched code.",
            "properties": {
              "count": {
                "title": "Replace up to this many regex matches",
                "type": "integer"
              },
              "regex": {
                "title": "Regular expression to find in matched code",
                "type": "string"
              },
              "replacement": {
                "title": "Code to replace the regular expression match with. Can use capture groups.",
                "type": "string"
              }
            },
            "required": ["regex", "replacement"],
            "additionalProperties": false
          },
          "metadata": {
            "title": "Arbitrary structured data for your own reference",
            "type": "object"
          },
          "options": {
            "title": "Options object to enable/disable certain matching features in semgrep-core",
            "type": "object"
          },
          "pattern": {
            "title": "Return finding where Semgrep pattern matches exactly",
            "type": "string"
          },
          "pattern-regex": {
            "title": "Return finding where regular expression matches exactly",
            "type": "string"
          },
          "patterns": {
            "$ref": "#/$defs/patterns-content"
          },
          "pattern-either": {
            "$ref": "#/$defs/pattern-either-content"
          },
          "r2c-internal-project-depends-on": {
            "$ref": "#/$defs/r2c-internal-project-depends-on-content"
          },
          "extract": {
            "title": "Metavariable whose content to use as the extracted result for subsequent rules",
            "type": "string"
          },
          "dest-language": {
            "title": "Language to process the extracted result of this rule as",
            "type": "string"
          },
          "reduce": {
            "title": "Method of intrafile match reduction",
            "enum": ["concat", "separate"],
            "default": "separate"
          }
        },
        "additionalProperties": false,
        "allOf": [
          {
            "if": {
              "properties": {
                "mode": {
                  "const": "extract"
                }
              },
              "required": ["mode"]
            },
            "then": {
              "required": ["id", "languages", "dest-language", "extract"],
              "oneOf": [
                {
                  "required": ["pattern"]
                },
                {
                  "required": ["patterns"]
                },
                {
                  "required": ["pattern-either"]
                },
                {
                  "required": ["pattern-regex"]
                }
              ],
              "properties": {
                "message": false,
                "severity": false,
                "pattern-sinks": false,
                "pattern-sources": false,
                "pattern-propagators": false,
                "pattern-sanitizers": false,
                "join": false
              }
            }
          },
          {
            "if": {
              "properties": {
                "mode": {
                  "const": "taint"
                }
              },
              "required": ["mode"]
            },
            "then": {
              "required": [
                "id",
                "message",
                "languages",
                "severity",
                "pattern-sinks",
                "pattern-sources"
              ],
              "properties": {
                "extract": false,
                "dest-language": false,
                "reduce": false,
                "pattern": false,
                "patterns": false,
                "pattern-either": false,
                "pattern-regex": false,
                "join": false
              }
            }
          },
          {
            "if": {
              "properties": {
                "mode": {
                  "const": "join"
                }
              },
              "required": ["mode"]
            },
            "then": {
              "required": ["id", "message", "severity", "join"],
              "properties": {
                "extract": false,
                "dest-language": false,
                "reduce": false,
                "patterns": false,
                "pattern": false,
                "pattern-either": false,
                "pattern-regex": false,
                "pattern-sinks": false,
                "pattern-sources": false,
                "pattern-propagators": false,
                "pattern-sanitizers": false
              }
            }
          },
          {
            "if": {
              "properties": {
                "mode": {
                  "const": "search"
                }
              }
            },
            "then": {
              "required": ["id", "message", "languages", "severity"],
              "if": {
                "anyOf": [
                  {
                    "required": ["pattern"]
                  },
                  {
                    "required": ["patterns"]
                  },
                  {
                    "required": ["pattern-either"]
                  },
                  {
                    "required": ["pattern-regex"]
                  }
                ]
              },
              "then": {
                "oneOf": [
                  {
                    "required": ["pattern"]
                  },
                  {
                    "required": ["patterns"]
                  },
                  {
                    "required": ["pattern-either"]
                  },
                  {
                    "required": ["pattern-regex"]
                  }
                ]
              },
              "else": {
                "oneOf": [
                  {
                    "required": ["pattern"]
                  },
                  {
                    "required": ["patterns"]
                  },
                  {
                    "required": ["pattern-either"]
                  },
                  {
                    "required": ["pattern-regex"]
                  },
                  {
                    "required": ["r2c-internal-project-depends-on"]
                  }
                ]
              },
              "properties": {
                "extract": false,
                "dest-language": false,
                "reduce": false,
                "pattern-sinks": false,
                "pattern-sources": false,
                "pattern-propagators": false,
                "pattern-sanitizers": false,
                "join": false
              }
            }
          }
        ]
      }
    }
  },
  "type": "object"
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://meltano.com/meltano.schema.json",
  "title": "JSON Schema for meltano.yml",
  "description": "Meltano (https://meltano.com) is an open source platform for building, running & orchestrating ELT pipelines",
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "version": {
      "const": 1
    },
    "annotations": {
      "$ref": "#/$defs/annotations"
    },
    "default_environment": {
      "type": "string",
      "description": "A default environment to be used when one is not present as an argument or as an environment variable."
    },
    "send_anonymous_usage_stats": {
      "type": "boolean",
      "description": "Share anonymous usage data with the Meltano team to help them gauge interest and allocate development time",
      "default": true
    },
    "project_id": {
      "type": "string",
      "description": "A globally unique project identifier. Defaults to a Meltano-generated unique GUID for each project."
    },
    "database_uri": {
      "type": "string",
      "description": "A database URI for the project system database. Defaults to a SQLite file stored at .meltano/meltano.db",
      "default": "sqlite:///$MELTANO_PROJECT_ROOT/.meltano/meltano.db"
    },
    "python": {
      "type": "string",
      "description": "The python version to use for plugins, specified as a path, or as the name of an executable to find within a directory in $PATH. If not specified, the python executable that was used to run Meltano will be used (within a separate virtual environment). This can be overridden on a per-plugin basis by setting the `python` property for the plugin.",
      "examples": [
        "/usr/bin/python3.10",
        "python",
        "python3.11"
      ]
    },
    "state_backend": {
      "type": "object",
      "description": "Configuration for state backend.",
      "properties": {
        "uri": {
          "type": "string",
          "description": "The URI pointing to the backend to use.",
          "default": "systemdb"
        },
        "lock_timeout_seconds": {
          "type": "integer",
          "description": "The number of seconds a lock on a state file is considered valid."
        },
        "lock_retry_seconds": {
          "type": "integer",
          "description": "The number of seconds to wait between retrying lock acquisition."
        },
        "azure": {
          "type": "object",
          "description": "Configuration for Azure Blob Storage state backend.",
          "properties": {
            "connection_string": {
              "type": "string",
              "description": "The azure connection string to use for connecting to Azure Blob Storage."
            }
          }
        },
        "gcs": {
          "type": "object",
          "description": "Configuration for Google Cloud Storage state backend.",
          "properties": {
            "application_credentials": {
              "type": "string",
              "description": "Path to a Google credentials file to use for authenticating to Google Cloud Storage."
            }
          }
        },
        "s3": {
          "type": "object",
          "description": "Configuration for AWS S3 state backend.",
          "properties": {
            "aws_access_key_id": {
              "type": "string",
              "description": "AWS access key ID to use for authenticating to AWS S3."
            },
            "aws_secret_access_key": {
              "type": "string",
              "description": "AWS secret access key to use for authenticating to AWS S3."
            },
            "endpoint_url": {
              "type": "string",
              "description": "S3 endpoint URL to use."
            }
          }
        }
      }
    },
    "environments": {
      "type": "array",
      "description": "An array of environments (i.e. dev, stage, prod) with override configs for plugins based on the environment its run in.",
      "items": {
        "$ref": "#/$defs/environments"
      }
    },
    "discovery_url": {
      "type": "string",
      "description": "URL to remote manifest of Meltano plugins, used by meltano discover. Set to 'false' to disable.",
      "default": "https://www.meltano.com/discovery.yml"
    },
    "include_paths": {
      "type": "array",
      "description": "An array of paths (relative to the project directory) of other Meltano config files to include in the configuration.",
      "items": {
        "type": "string"
      }
    },
    "plugins": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "extractors": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/plugins/extractors"
          }
        },
        "loaders": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/plugins/loaders"
          }
        },
        "mappers": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/plugins/mappers"
          }
        },
        "orchestrators": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/plugins/orchestrators"
          }
        },
        "transformers": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/plugins/transformers"
          }
        },
        "files": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/plugins/files"
          }
        },
        "utilities": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/plugins/utilities"
          }
        },
        "transforms": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/plugins/transforms"
          }
        }
      }
    },
    "schedules": {
      "type": "array",
      "items": {
        "$ref": "#/$defs/schedules"
      },
      "description": "Scheduled ELT jobs, added using 'meltano schedule'"
    },
    "env": {
      "$ref": "#/$defs/env"
    },
    "jobs": {
      "type": "array",
      "items": {
        "$ref": "#/$defs/jobs"
      },
      "description": "Jobs, added using 'meltano job'"
    },
    "database_max_retries": {
      "type": "integer",
      "description": "The number of times to retry connecting to the Meltano database.",
      "default": 3,
      "minimum": 0
    },
    "database_retry_timeout": {
      "type": "integer",
      "description": "The time in seconds to wait between Meltano database connection attempts.",
      "default": 5,
      "minimum": 0
    },
    "cli": {
      "type": "object",
      "description": "CLI related settings.",
      "properties": {
        "log_config": {
          "type": "string",
          "description": "The path to the logging config, relative to the Meltano project root.",
          "default": "logging.yaml"
        }
      }
    },
    "elt": {
      "type": "object",
      "description": "ELT related settings",
      "properties": {
        "buffer_size": {
          "type": "integer",
          "description": "The size of the ELT buffer in bytes.",
          "default": 10485760
        }
      }
    },
    "experimental": {
      "type": "boolean",
      "description": "Whether experimental features should be enabled.",
      "default": false
    },
    "ff": {
      "type": "object",
      "description": "A feature flag, which can be used to enable or disable particular Meltano features.",
      "properties": {
        "enable_uvicorn": {
          "type": "boolean",
          "description": "Whether to use Uvicorn rather than Gunicorn as the API server.",
          "default": false
        },
        "enable_api_scheduled_job_list": {
          "type": "boolean",
          "description": "Whether the API includes scheduled jobs in listings.",
          "default": false
        },
        "strict_env_var_mode": {
          "type": "boolean",
          "description": "Whether references to undefined environment variables cause Meltano to exit with an error.",
          "default": false
        },
        "plugin_locks_required": {
          "type": "boolean",
          "description": "Whether plugin locks are required to run a job.",
          "default": false
        }
      }
    },
    "hub_api_root": {
      "type": [
        "string",
        "null"
      ],
      "description": "The URL to the root of the Meltano Hub API.",
      "default": null,
      "examples": [
        "https://hub.meltano.com/meltano/api/v1"
      ]
    },
    "hub_url": {
      "type": "string",
      "description": "The URL for Meltano Hub.",
      "default": "https://hub.meltano.com"
    },
    "hub_url_auth": {
      "type": [
        "string",
        "boolean",
        "null"
      ],
      "description": "The value of the `Authorization` header when making requests to Meltano Hub. If null, false, or unset, no `Authorization` header is used.",
      "default": null,
      "examples": [
        "Bearer $ACCESS_TOKEN"
      ]
    },
    "snowplow": {
      "type": "object",
      "description": "Snowplow related settings.",
      "properties": {
        "collector_endpoints": {
          "type": "array",
          "description": "Array of Snowplow collector endpoints.",
          "items": {
            "type": "string",
            "description": "A URL to which Snowplow events will be sent if telemetry is enabled."
          },
          "default": [
            "https://sp.meltano.com"
          ]
        }
      }
    }
  },
  "$defs": {
    "annotations": {
      "type": "object",
      "description": "Arbitrary annotations keyed by tool/vendor name - not processed by the core Meltano library or CLI",
      "propertyNames": {
        "type": "string"
      },
      "additionalProperties": {
        "type": "object"
      }
    },
    "plugins": {
      "plugin_generic": {
        "type": "object",
        "required": [
          "name"
        ],
        "properties": {
          "annotations": {
            "$ref": "#/$defs/annotations"
          },
          "name": {
            "type": "string",
            "description": "The name of the plugin.",
            "examples": [
              "target-jsonl"
            ]
          },
          "description": {
            "type": "string",
            "description": "A description of the plugin."
          },
          "plugin_type": {
            "type": "string",
            "description": "The type of the plugin.",
            "enum": [
              "extractors",
              "loaders",
              "orchestrators",
              "transformers",
              "files",
              "utilities",
              "transforms",
              "mappers"
            ]
          },
          "repo": {
            "type": "string",
            "description": "The URL of the repository containing the source code for the plugin."
          },
          "ext_repo": {
            "type": "string",
            "description": "The URL of the repository containing the source code for a Meltano extension plugin that typically wraps some other tool, in which case the 'repo' property is used for the URL of the repository for that tool."
          },
          "inherit_from": {
            "type": "string",
            "description": "An existing plugin to inherit from."
          },
          "pip_url": {
            "type": "string",
            "description": "The pip hosted package name or URL",
            "examples": [
              "target-jsonl",
              "git+https://gitlab.com/meltano/tap-facebook.git",
              "wtforms==2.2.1 apache-airflow==1.10.2"
            ]
          },
          "variant": {
            "type": "string",
            "description": "The variant of the plugin."
          },
          "namespace": {
            "type": "string",
            "description": "The namespace of this plugin",
            "examples": [
              "tap_csv",
              "target_jsonl"
            ]
          },
          "config": {
            "type": "object",
            "description": "Your plugin configuration, type 'meltano config <plugin> list' for details"
          },
          "label": {
            "type": "string",
            "description": "A user friendly label describing the plugin",
            "examples": [
              "Stripe",
              "Facebook Ads"
            ]
          },
          "logo_url": {
            "type": "string",
            "description": "An optional logo URL for this plugin"
          },
          "python": {
            "type": "string",
            "description": "The python version to use for this plugin, specified as a path, or as the name of an executable to find within a directory in $PATH. If not specified, the top-level `python` setting will be used, or if it is not set, the python executable that was used to run Meltano will be used (within a separate virtual environment).",
            "examples": [
              "/usr/bin/python3.10",
              "python",
              "python3.11"
            ]
          },
          "executable": {
            "type": "string",
            "description": "The plugin's executable name, as defined in setup.py (if a Python based plugin)",
            "examples": [
              "tap-stripe",
              "tap-covid-19"
            ]
          },
          "settings": {
            "type": "array",
            "items": {
              "$ref": "#/$defs/base_setting"
            }
          },
          "docs": {
            "type": "string",
            "description": "A URL to the documentation for this plugin"
          },
          "settings_group_validation": {
            "type": "array",
            "items": {
              "type": "array",
              "description": "A set consisting of one valid combination of required setting names",
              "items": {
                "type": "string"
              }
            }
          },
          "commands": {
            "type": "object",
            "description": "A mapping of command names to either a string command, or an object containing info about the command.",
            "additionalProperties": {
              "oneOf": [
                {
                  "type": "object",
                  "required": [
                    "args"
                  ],
                  "properties": {
                    "annotations": {
                      "$ref": "#/$defs/annotations"
                    },
                    "args": {
                      "type": "string",
                      "description": "Command arguments"
                    },
                    "description": {
                      "type": "string",
                      "description": "Documentation displayed when listing commands"
                    },
                    "executable": {
                      "type": "string",
                      "description": "Override the plugin's executable for this command"
                    },
                    "container_spec": {
                      "type": "object",
                      "required": [
                        "image"
                      ],
                      "description": "Container specification for this command",
                      "properties": {
                        "annotations": {
                          "$ref": "#/$defs/annotations"
                        },
                        "image": {
                          "type": "string",
                          "description": "Container image",
                          "examples": [
                            "ghcr.io/dbt-labs/dbt-postgres:latest"
                          ]
                        },
                        "command": {
                          "type": "string",
                          "description": "Container command",
                          "examples": [
                            "list",
                            "test",
                            "compile"
                          ]
                        },
                        "entrypoint": {
                          "type": "string",
                          "description": "Container entrypoint"
                        },
                        "ports": {
                          "type": "object",
                          "description": "Mapping of host to container ports",
                          "propertyNames": {
                            "type": "string"
                          },
                          "additionalProperties": {
                            "type": "string"
                          },
                          "examples": [
                            {
                              "5000": "5000"
                            }
                          ]
                        },
                        "volumes": {
                          "type": "array",
                          "description": "Array of volumes to mount during container execution",
                          "items": {
                            "type": "string",
                            "examples": [
                              "$MELTANO_PROJECT_ROOT/transform/:/usr/app/"
                            ]
                          }
                        },
                        "env": {
                          "type": "object",
                          "description": "Mapping to environment variable to set inside the container. These take precedence over Meltano own runtime environment variables.",
                          "propertyNames": {
                            "type": "string"
                          },
                          "additionalProperties": {
                            "type": "string"
                          },
                          "examples": [
                            {
                              "DBT_PROFILES_DIR": "/usr/app/profile/"
                            }
                          ]
                        }
                      }
                    }
                  }
                },
                {
                  "type": "string",
                  "description": "The command as a string."
                }
              ]
            }
          },
          "requires": {
            "$ref": "#/$defs/requires"
          },
          "env": {
            "$ref": "#/$defs/env"
          }
        }
      },
      "extractor_shared": {
        "type": "object",
        "properties": {
          "annotations": {
            "$ref": "#/$defs/annotations"
          },
          "catalog": {
            "type": "string",
            "description": "A path to a catalog file (relative to the project directory) to be provided to the extractor when it is run in sync mode."
          },
          "load_schema": {
            "type": "string",
            "description": "The name of the database schema extracted data should be loaded into."
          },
          "metadata": {
            "type": "object",
            "description": "An object containing Singer stream and property metadata",
            "default": {}
          },
          "schema": {
            "type": "object",
            "description": "An object representing override rules for a Singer stream schema",
            "default": {}
          },
          "state": {
            "type": "string",
            "description": "A path to a state file (relative to the project directory) to be provided to the extractor when it is run as part of a pipeline using meltano elt."
          },
          "select": {
            "type": "array",
            "default": [
              "*.*"
            ],
            "description": "An array of entity selection rules in the form '<entity|*>.<attribute|*>'",
            "items": {
              "type": "string"
            }
          },
          "select_filter": {
            "type": "array",
            "description": "An array of entity selection filter rules that are applied to the extractor's discovered or provided catalog file when the extractor is run.",
            "items": {
              "type": "string"
            },
            "default": []
          }
        }
      },
      "extractors": {
        "description": "https://docs.meltano.com/concepts/plugins#extractors",
        "type": "object",
        "allOf": [
          {
            "$ref": "#/$defs/plugins/plugin_generic"
          },
          {
            "$ref": "#/$defs/plugins/extractor_shared"
          },
          {
            "type": "object",
            "properties": {
              "capabilities": {
                "type": "array",
                "items": {
                  "type": "string",
                  "enum": [
                    "properties",
                    "catalog",
                    "discover",
                    "state",
                    "about",
                    "stream-maps",
                    "activate-version",
                    "batch",
                    "test",
                    "log-based",
                    "schema-flattening"
                  ]
                }
              }
            }
          }
        ],
        "unevaluatedProperties": false
      },
      "loaders": {
        "description": "https://docs.meltano.com/concepts/plugins#loaders",
        "type": "object",
        "allOf": [
          {
            "$ref": "#/$defs/plugins/plugin_generic"
          },
          {
            "properties": {
              "capabilities": {
                "type": "array",
                "items": {
                  "type": "string",
                  "enum": [
                    "about",
                    "stream-maps",
                    "activate-version",
                    "batch",
                    "soft-delete",
                    "hard-delete",
                    "datatype-failsafe",
                    "record-flattening"
                  ]
                }
              },
              "dialect": {
                "type": "string",
                "description": "The name of the dialect of the target database, so that transformers in the same pipeline and Meltano UI's Analysis feature can determine the type of database to connect to."
              },
              "target_schema": {
                "type": "string",
                "description": "The name of the database schema the loader has been configured to load data into (assuming the destination supports schemas), so that transformers in the same pipeline can determine the database schema to load data from."
              }
            }
          }
        ],
        "unevaluatedProperties": false
      },
