                  "type": "array",
                  "items": {
                    "unevaluatedProperties": false,
                    "$ref": "#/$defs/environments/$defs/plugins"
                  }
                },
                "transformers": {
                  "type": "array",
                  "items": {
                    "unevaluatedProperties": false,
                    "$ref": "#/$defs/environments/$defs/plugins"
                  }
                },
                "files": {
                  "type": "array",
                  "items": {
                    "unevaluatedProperties": false,
                    "$ref": "#/$defs/environments/$defs/plugins"
                  }
                },
                "utilities": {
                  "type": "array",
                  "items": {
                    "unevaluatedProperties": false,
                    "$ref": "#/$defs/environments/$defs/plugins"
                  }
                },
