        },
        "traceSettingsString": {
          "type": "string",
          "description": "String with processor trace encoder settings required by the decoder"
        },
        "libsDirectory": {
          "$ref": "#/$defs/supportPackDirectory",
          "description": "Directory containing library files for use with the platform"
