  "properties": {
    "_metadata": {
      "description": "Settings that describe the manifest.\nhttps://api.slack.com/reference/manifests#metadata",
      "type": "object",
      "properties": {
        "major_version": {
          "description": "An integer that specifies the major version of the manifest schema to target.",
          "type": "integer"
        },
