            "required": ["command", "description"],
            "additionalProperties": false
          }
        },
        "unfurl_domains": {
          "description": "Valid unfurl domains to register. Please consult the unfurl docs for a list of domain requirements.",
          "type": "array",
          "items": {
            "type": "string"
          },
          "maxItems": 5
        },
        "workflow_steps": {
