        },
        "doc-url": {
          "$ref": "#/definitions/doc-url"
        },
        "icon": {
          "$ref": "#/definitions/icon"
        },
        "source": {
          "$ref": "#/definitions/source"
        },
        "deprecated": {
          "$ref": "#/definitions/deprecated"
        },
        "experimental": {
          "$ref": "#/definitions/experimental"
        },
        "priority": {
